from research_helpers import source, assessment, record, scope, evidence, decision, write_batch

refs=[
 ('replicant','Nier plot and gameplay','Wikipedia contributors','https://en.wikipedia.org/wiki/Nier_(video_game)','The Replicant protagonist earns money through odd jobs, while farming/fishing and human-derived bodies remain central.','The soul/body preservation project does not itself replace ordinary productive work.'),
 ('cage','The Cage','NIER Wiki contributors','https://nier.fandom.com/wiki/The_Cage','The lunar server archives human history and divergent memories; guides and an android maintain it.','The short reference mixes archives and experienced digital worlds; active-person/resource scope remains unresolved.'),
 ('horizon-income','Secret Show','Horizon Zero Dawn: The Frozen Wilds datapoint, transcribed by Horizon Wiki','https://horizon.fandom.com/wiki/Secret_Show','The bounded message describes Faro servitors replacing dam workers and basic income as the alternative.','A single localized employment account, not a world census or proof of adequate benefits; indexed text only, not a full archive read.'),
 ('horizon-income-limits','Bayhas Mati','Horizon Wiki contributors','https://horizon.fandom.com/wiki/Bayhas_Mati','Robot-maintenance pay measured against basic income can fail to cover food and rent; fines threaten a family’s finances.','A particular family’s history qualifies broad adequacy claims, not every benefit recipient’s identical experience.'),
 ('horizon-oldworld-reading','Horizon Zero Dawn review','Jonas Liljegren','https://blog.jonas.liljegren.org/horizon-zero-dawn/','The reviewer describes Old World robotics, domestic servitors and universal basic income.','Secondary game reading, used with a concrete transcribed displacement account; not a detailed global benefits charter.'),
 ('eleuthia','ELEUTHIA','Horizon Wiki contributors','https://horizon.fandom.com/wiki/ELEUTHIA','Cradles actually birth and raise humans with servitor care; lost education and depleted food force the first generation outside.','Real childhood provision is distinct from the original planned educated civilization; no inference of inexhaustible food manufacturing.'),
 ('gaia-ecology','Machines in Horizon','Wikipedia contributors','https://en.wikipedia.org/wiki/Machines_%28Horizon%29','Automatic terraforming restores the biosphere, while later tribes hunt machines for resources.','Ecosystem support is not universal work-independent food/housing allocation.'),
 ('sirius','Sirius','Horizon Wiki contributors','https://horizon.fandom.com/wiki/Sirius','Far Zenith establishes an actual colony and lives largely through indulgent virtual experiences; later destruction has a concealed cause.','Tilda’s claimed geological catastrophe is a cover story, not adopted factual history.'),
 ('far-zenith','Far Zenith','Horizon Wiki contributors','https://horizon.fandom.com/wiki/Far_Zenith','The elite consortium controls an advanced colony and printing facilities, achieves physical longevity and spends much of life in VR before Nemesis destroys it.','Indexed history sections, not a direct full-page read; Nemesis’s later seizure does not establish earlier AI sovereignty.'),
 ('alliance-codex','Codex: Humanity and the Systems Alliance','Mass Effect in-game codex, transcribed by Mass Effect Wiki','https://masseffect.fandom.com/wiki/Codex/Humanity_and_the_Systems_Alliance','Resource imports and longer lives coexist with industrial labor, national differences and widening poverty gaps.','A concrete human example, not the whole Council’s homogeneous economic constitution. Fanfiction claiming universal energy dividends was discarded.'),
 ('geth','Geth','Wikipedia contributors','https://en.wikipedia.org/wiki/Geth','Networked artificial intelligences have engineering and military platforms and maintain Rannoch.','Artificial collective intelligence alone does not establish a human-person population or a post-work allocation mechanism.'),
 ('rannoch-care','Quarian helmets on Rannoch discussion','GameFAQs contributors','https://gamefaqs.gamespot.com/boards/995452-mass-effect-3/65173168','A bounded comment recounts Tali’s conditional geth-assisted immune adaptation after peace.','Informal dialogue recollection only; misleading comments are not adopted and the care arrangement does not establish a whole economy.'),
 ('me3-ending-context','Mass Effect 3 story and endings','Joe Garratt, LoreFortress','https://www.lorefortress.com/mass-effect/mass-effect-3-ending-explained','The overview distinguishes Destroy, Control, Synthesis and Refuse, with Reaper aid after Control.','Recent secondary overview, used only for branch context and an explicit remaining gap; no guaranteed material floor or population statistic is inferred.'),
 ('control-capture','Mass Effect 3 Extended Cut: Control ending capture','J.C.’s Channel','https://www.youtube.com/watch?v=wOKCYIj48sk','The uploader’s description identifies a paragon Control playthrough with Reaper reconstruction and peacekeeping.','Description only, not a watched video or a full spoken-ending transcript; paragon and renegade variants are not collapsed.'),
 ('reapers','Reapers in Mass Effect','Wikipedia contributors','https://en.wikipedia.org/wiki/Reapers_%28Mass_Effect%29','Synthetic-organic ships harvest civilizations, then remain dormant between cycles.','Harvested DNA and long dormancy are not surviving individuals enjoying post-work leisure.')
]
S=[source('src-b76-'+sid,title,author,url,'game_reference_or_indexed_datapoint','Short public reference or honestly labeled indexed passage',claim,limits) for sid,title,author,url,claim,limits in refs]
o=['src-b76-horizon-income','src-b76-horizon-income-limits','src-b76-horizon-oldworld-reading'];e=['src-b76-eleuthia'];z=['src-b76-sirius','src-b76-far-zenith']
R=[
 record('horizon-oldworld-basic-income','c0607','Horizon Zero Dawn — Old World automation and basic income','Horizon Zero Dawn','Documented Old World basic-income regions amid robotic job replacement',['game'],
 scope('Horizon Zero Dawn and The Frozen Wilds datapoints','The pre-Faro-Plague automation era represented by dam-worker and family records','Living people in the documented basic-income economy',['Identical benefits worldwide','The later tribal economy','The Faro Plague emergency','Every recipient as completely nonworking']),
 'Old World records connect robot replacement directly with basic income: dam employees face Faro servitors taking their jobs and name that benefit as the alternative. This supports a partial post-work income arrangement, rather than merely the existence of advanced robots. It does not establish comfortable universal provision. A separate family account describes robot-maintenance earnings measured against the benefit baseline failing to cover food and rent, so the guarantee estimate remains weak and broad. The record is limited to the documented economy, without assigning identical rules to every country.\n\nCompanies control the productive servitors and employment decisions; no broad resident ownership of the machinery is established. The control point therefore lies near concentrated human authority, despite considerable automatic operation. Income received without the replaced job weakens wage dependence, but its adequacy, eligibility and purchasing power remain uncertain. Neither unemployment nor benefit receipt tells us how many people perform useful work. Maintenance, art, care and other chosen activity still count, so participation stays unresolved. The later Faro emergency and tribal subsistence are different periods.',
 {'guarantees':0.55,'control':0.05,'nonworking':None},
 {'guarantees':assessment(0.55,[0.05,0.9],'low','A basic-income fallback exists, but documented hardship shows that an income baseline need not secure food and housing.',o),
  'control':assessment(0.05,[0,0.25],'low','Corporate owners install replacement servitors; collective ownership or decisive independent AI rule is not established.',o),
  'nonworking':assessment(None,None,'low','Displacement and benefit eligibility do not census all useful work.',o)},
 3,o,[evidence('Faro servitors replace dam jobs while basic income is named as the fallback; other records qualify adequacy.',o,'Secret Show message, Bayhas family history and Old World review','indexed_primary_datapoint_and_secondary_context')],
 ['Partial transition with uncertain benefit coverage and adequacy.', 'Documented regions, not a verified uniform worldwide constitution.', 'Job loss does not equal no useful work.', 'Pre-Plague period only.'],alternatives=[1]),
 record('horizon-eleuthia9-first-generation','c0608','Horizon Zero Dawn — ELEUTHIA’s first cradle generation','Horizon Zero Dawn','Actual human children raised by automated cradle servitors',['game'],
 scope('Horizon Zero Dawn project history','The first generation’s real childhood before food depletion and release','Living children raised in the implemented cradle system',['Unborn stored zygotes as active people','The unimplemented APOLLO-educated civilization','Later self-supporting tribes','An inexhaustible food-production system']),
 'ELEUTHIA actually births and raises a new human generation, supplying necessities through cradle facilities and robotic carers, healers and disciplinarians. These children receive support without earning wages or relying on an ongoing living human parent workforce. The record concerns that implemented childhood arrangement, rather than the entire educated civilization originally planned by Zero Dawn. Stored provisions eventually run out, forcing release into the outside world; a finite but long-running support system is not an inexhaustible cornucopia.\n\nWith the original human builders gone, effective provision belongs to the machine system, not to the children. The negative control point reflects that absence of current human command, without assuming every subordinate function has the same independent agency. Guarantees are only moderately strong and highly uncertain because access lasts through childhood but the system fails to provide the intended continuing education and adult transition. Learning, care and practical help can be useful work, so childhood is not converted into a nonworking percentage. Unborn zygotes and later tribal descendants are excluded from the active supported population.',
 {'guarantees':-0.35,'control':-0.85,'nonworking':None},
 {'guarantees':assessment(-0.35,[-0.8,0.65],'low','Actual childhood care persists, but finite supplies and forced release sharply bound the support promise.',e),
  'control':assessment(-0.85,[-1,-0.5],'medium','Machine institutions provide care after the human builders’ deaths; recipients cannot collectively direct the facilities.',e),
  'nonworking':assessment(None,None,'low','Children’s learning and help may be useful; no all-person participation rate is established.',e)},
 5,e,[evidence('The cradles successfully raise humans through servitor care, then release them when supplies fail.',e,'ELEUTHIA implementation/results and first-generation release','secondary_game_reference_with_datapoint_citations')],
 ['Actual cradle generation, not the complete planned civilization.', 'Stored food and robotic care are distinguished from unlimited production.', 'Finite support and failed adult transition qualify guarantees.', 'Unborn preserved material is not active leisure.'],alternatives=[6]),
 record('horizon-far-zenith-sirius-colony','c0610','Horizon Forbidden West — Far Zenith’s Sirius colony','Horizon Forbidden West','The technologically sustained elite colony before Nemesis’s escape',['game'],
 scope('Horizon Forbidden West history','Established Sirius colony life before Nemesis destroys it','Living embodied Far Zenith colonists',['Earth’s excluded population','Nemesis’s imprisoned mind copies as equal colonists','The surviving invaders after the colony’s destruction','Tilda’s false geological disaster account']),
 'Far Zenith establishes a real off-world colony with advanced fabrication and bodily maintenance, allowing its living elite to spend much of an exceptionally long life in virtual indulgence. Their access rests on membership in an enclosed technological colony, not current ordinary employment. Guarantees are rated fairly strong within that narrow cohort, while remaining uncertain because individual rights and the division of resources are not described. This does not grant the same security to everyone abandoned on Earth or to the mind copies imprisoned in the failed immortality experiment.\n\nThe consortium and its leaders control the colony and printing infrastructure. Nemesis later seizes those systems, but that disaster does not make the preceding order an AI-run society. A high, low-confidence nonworking estimate follows the explicitly indulgent lifestyle, with a wide allowance for continued scientific work, care and administration. Useful research remains work, even among immortals. The record stops before the colony’s destruction and rejects Tilda’s false account of a natural catastrophe; later fleeing survivors do not automatically retain the same material floor.',
 {'guarantees':-0.6,'control':0.05,'nonworking':0.8},
 {'guarantees':assessment(-0.6,[-0.9,0.3],'low','Long-lasting technological provision supports the resident elite, but individual rights and internal exclusions are incompletely described.',z),
  'control':assessment(0.05,[0,0.2],'medium','Human consortium leadership owns the infrastructure before Nemesis’s hostile seizure.',z),
  'nonworking':assessment(0.8,[0.5,1],'low','The sources describe largely indulgent virtual life; the broad noncanonical estimate allows useful ongoing research and service.',z)},
 1,z,[evidence('The established elite colony combines printing infrastructure, physical longevity and a largely virtual leisure lifestyle.',z,'Sirius establishment and Far Zenith colonization/fall sections','indexed_secondary_game_lore')],
 ['Elite embodied cohort only, not all Earth or imprisoned digital copies.', 'Before Nemesis’s seizure and destruction.', 'No disputed exact population or lifespan arithmetic is used.', 'Participation is an explicit editorial estimate.'])
]
rows=[
 ('c0605','boundary_case',['replicant'],'Replicant society retains real jobs, farming and fishing despite artificial bodies and the Gestalt preservation project.','Body/soul separation is not a general labor-independent production and distribution system.'),
 ('c0606','needs_evidence',['cage'],'The Cage’s memory worlds lack a sufficiently clear active-person and material-access scope.','Archived history, divergent memories and active experiences cannot be treated as one fully supplied population without further evidence.'),
 ('c0609','boundary_case',['gaia-ecology'],'GAIA’s terraforming supports an ecosystem while tribal humans perform real subsistence work.','Machine hunting and biological restoration are not universal household allocation or a deliberately preserved unnecessary job system.'),
 ('c0611','needs_evidence',['alliance-codex'],'The Council sphere is not established as one work-independent household economy.','The human codex shows industry, resource imports and unequal conditions; fanfiction proposing universal automatic dividends was discarded.'),
 ('c0612','needs_evidence',['geth'],'Geth consensus does not by itself establish post-work allocation or a justified human-person participation scope.','An engineering/military synthetic population is not equivalent to supplied nonworking humans; consensus alone does not settle material access.'),
 ('c0613','needs_evidence',['rannoch-care','geth'],'Geth-assisted resettlement and immune care do not establish Rannoch’s complete household economy.','A conditional care recollection is relevant but insufficient for ordinary access, ownership or all-person work estimates.'),
 ('c0614','needs_evidence',['me3-ending-context'],'Synthesis’s biological/technical transformation does not establish a detailed post-work resource constitution.','Ending peace and shared knowledge do not by themselves supply food/housing entitlements or effective productive ownership; no best-ending claim is adopted.'),
 ('c0615','needs_evidence',['me3-ending-context','control-capture'],'Reaper reconstruction under the Control branch does not establish ordinary labor-independent provision.','Shepard’s guardian role and construction aid are distinct from a completed universal material floor; paragon and renegade choices may differ.'),
 ('c0616','boundary_case',['reapers'],'Reaper harvest and dormancy are not preserved individuals enjoying a post-work support system.','Processed organic material and synthetic-organic warships do not supply an active human welfare denominator.')
]
D=[decision(cid,status,reason,['src-b76-'+s for s in ss],analysis=analysis,follow_up='Retain the short gap/comparison and continue; no full-lore reconstruction or speculative rights after an ending.') for cid,status,ss,reason,analysis in rows]
D += [decision(cid,'included',reason,ss,society_id=rid) for cid,rid,ss,reason in [('c0607',R[0]['id'],o,'Documented basic income accompanies real robotic job replacement, with explicit adequacy limitations.'),('c0608',R[1]['id'],e,'The planned project actually implements a continuing robot-supported human childhood cohort, separately from its failed wider aims.'),('c0610',R[2]['id'],z,'The established elite colony combines advanced fabrication and continuing bodily provision with widespread virtual leisure.')]]
D.sort(key=lambda x:x['candidate_id'])
write_batch(76,[f'c{i:04}' for i in range(605,617)],S,R,D,[
 'Twelve fast decisions and three records. Primary checking stayed within the short Secret Show message; no complete game transcript or novel was read.',
 'Horizon’s basic-income economy, implemented cradle childhood, later tribal subsistence and Sirius elite colony are separate scopes.',
 'ELEUTHIA’s frozen zygotes are not active people; finite robot care need not imply unlimited fabrication. Far Zenith remains human-controlled before Nemesis takes over.',
 'Mass Effect fanfiction offered exactly the desired universal-dividend economy, but was discarded. Ending transformation and reconstruction are not automatically universal material entitlements.',
 'Blocked wiki and terminal routes were respected. Secondary summaries and informal care recollections are honestly labeled and do not justify unsupported coordinates.'
])
